------------------------------------------------------------ HELPERS UI (ARCEUS X SAFE)
local function mk(class, props, parent)
	local ok, o = pcall(function() return Instance.new(class) end)
	if not ok or not o then return nil end
	for k, v in pairs(props or {}) do
		pcall(function() o[k] = v end)
	end
	if parent then
		pcall(function() o.Parent = parent end)
	end
	return o
end
local function corner(o, r)
	if not o then return nil end
	return mk("UICorner", {CornerRadius = UDim.new(0, r)}, o)
end
local function stroke(o, col, th, tr)
	if not o then return nil end
	return mk("UIStroke", {Color = col, Thickness = th or 1, Transparency = tr or 0, ApplyStrokeMode = Enum.ApplyStrokeMode.Border}, o)
end
local function tw(o, t, props, style, dir)
	if not o then return nil end
	local tr = TweenService:Create(o, TweenInfo.new(t, style or Enum.EasingStyle.Quint, dir or Enum.EasingDirection.Out), props)
	tr:Play()
	return tr
end
local function text(parent, str, size, font, color, x, y, w, h, align)
	return mk("TextLabel", {
		Text = str, TextSize = size, Font = font, TextColor3 = color, BackgroundTransparency = 1, BorderSizePixel = 0,
		Position = UDim2.fromOffset(x, y), Size = UDim2.fromOffset(w, h),
		TextXAlignment = align or Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Center,
	}, parent)
end

------------------------------------------------------------ PARENT SEGURO PARA ARCEUS X
local function resolveGuiParent()
	local targets = {}
	if type(gethui) == "function" then
		local ok, gh = pcall(gethui)
		if ok and gh then targets[#targets + 1] = gh end
	end
	local okCore, coreGui = pcall(function() return game:GetService("CoreGui") end)
	if okCore and coreGui then targets[#targets + 1] = coreGui end
	if LP then
		local pg = LP:FindFirstChildOfClass("PlayerGui") or LP:WaitForChild("PlayerGui", 5)
		if pg then targets[#targets + 1] = pg end
	end
	for _, parentObj in ipairs(targets) do
		local testGui = mk("ScreenGui", {Name = "yoshzzk", ResetOnSpawn = false, IgnoreGuiInset = true,
			ZIndexBehavior = Enum.ZIndexBehavior.Sibling, DisplayOrder = 9999}, parentObj)
		if testGui and testGui.Parent == parentObj then
			return testGui
		end
	end
	return mk("ScreenGui", {Name = "yoshzzk", ResetOnSpawn = false, IgnoreGuiInset = true}, LP and LP:FindFirstChildOfClass("PlayerGui"))
end

