local uiscale = mk("UIScale", {}, main)
local function fit()
	if not gui or not uiscale then return end
	local vp = gui.AbsoluteSize
	if vp.X > 10 and vp.Y > 10 then
		uiscale.Scale = math.clamp(math.min((vp.X - 16) / W, (vp.Y - 46) / H), 0.42, 1.05)
	end
end
