local function icon(kind, parent)
	local box = mk("Frame", {AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(18, 18), BackgroundTransparency = 1}, parent)
	local fills, strokes = {}, {}
	local function rect(x, y, w, h, r, rot)
		local f = mk("Frame", {Position = UDim2.fromOffset(x, y), Size = UDim2.fromOffset(w, h), BackgroundColor3 = C.mute,
			BorderSizePixel = 0, Rotation = rot or 0}, box)
		if r then corner(f, r) end
		fills[#fills + 1] = f
	end
	local function ring(x, y, s, th)
		local f = mk("Frame", {Position = UDim2.fromOffset(x, y), Size = UDim2.fromOffset(s, s), BackgroundTransparency = 1, BorderSizePixel = 0}, box)
		corner(f, s / 2)
		strokes[#strokes + 1] = stroke(f, C.mute, th)
	end
	if kind == "user" then
		ring(5.5, 1.5, 7, 1.5); rect(3, 10, 12, 6, 3)
	elseif kind == "esp" then
		ring(1, 4.5, 16, 1.4); ring(6.5, 6.5, 5, 1.4)
	elseif kind == "weapons" then
		ring(2, 2, 14, 1.5); rect(8.2, 0, 1.6, 5); rect(8.2, 13, 1.6, 5); rect(0, 8.2, 5, 1.6); rect(13, 8.2, 5, 1.6)
	elseif kind == "vehicle" then
		rect(2, 7, 14, 6, 2); rect(4, 5, 10, 4, 2)
	elseif kind == "layers" then
		rect(2, 4, 14, 2.5, 1); rect(2, 8.2, 14, 2.5, 1); rect(2, 12.4, 14, 2.5, 1)
	elseif kind == "gear" then
		ring(5, 5, 8, 1.8)
		for i = 0, 5 do
			local ang = math.rad(i * 60)
			rect(9 + math.cos(ang) * 6.5 - 1.3, 9 + math.sin(ang) * 6.5 - 1.3, 2.6, 2.6, 1, i * 60)
		end
	end
	return {set = function(col)
		for _, f in ipairs(fills) do if f then f.BackgroundColor3 = col end end
		for _, s in ipairs(strokes) do if s then s.Color = col end end
	end}
end

local tabs, pages = {}, {}
local TAB_TITLES = {
	["Weapons"] = "Weapons",
	["ESP"] = "ESP Visuals",
	["Player"] = "Player",
	["Vehicle"] = "Vehicle",
	["Layers"] = "Layers",
	["Settings"] = "Settings",
}

local function selectTab(name)
	for n, t in pairs(tabs) do
		local on = (n == name)
		t.btn.BackgroundTransparency = on and 0.15 or 1
		t.stroke.Transparency = on and 0.45 or 1
		t.ic.set(on and Color3.fromRGB(245, 245, 252) or C.mute)
		pages[n].Visible = on
	end
	title.Text = TAB_TITLES[name] or name
end

local function makeTab(name, kind, y)
	local b = mk("TextButton", {Text = "", AutoButtonColor = false, AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.fromOffset(SIDE_W / 2, y),
		Size = UDim2.fromOffset(32, 32), BackgroundColor3 = C.field, BackgroundTransparency = 1, BorderSizePixel = 0}, side)
	corner(b, 6)
	local st = stroke(b, Color3.fromRGB(70, 70, 88), 1, 1)
	tabs[name] = {btn = b, ic = icon(kind, b), stroke = st}
	pages[name] = mk("Frame", {Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Visible = false}, content)
	conn(b.Activated:Connect(function() selectTab(name) end))
end

