local function makeSectionCard(page, x, y, w, h, secTitle, withDividerRight)
	local f = mk("Frame", {Position = UDim2.fromOffset(x, y), Size = UDim2.fromOffset(w, h),
		BackgroundColor3 = C.card, BackgroundTransparency = 0.25, BorderSizePixel = 0}, page)
	corner(f, 7); stroke(f, Color3.fromRGB(44, 44, 56), 1, 0.45)
	if withDividerRight then
		mk("Frame", {AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, 0, 0, 8), Size = UDim2.fromOffset(1.5, h - 16),
			BackgroundColor3 = C.accBright, BackgroundTransparency = 0.25, BorderSizePixel = 0}, f)
	end
	if secTitle then
		text(f, secTitle, 12, F.GothamMedium, C.mute, 0, 8, w, 16, Enum.TextXAlignment.Center)
		mk("Frame", {AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 27), Size = UDim2.fromOffset(48, 1),
			BackgroundColor3 = Color3.fromRGB(72, 72, 88), BorderSizePixel = 0}, f)
	end
	local topOff = secTitle and 34 or 10
	local sf = mk("ScrollingFrame", {Position = UDim2.fromOffset(0, topOff), Size = UDim2.new(1, 0, 1, -(topOff + 6)),
		BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 2, ScrollBarImageColor3 = C.accBright,
		CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, ScrollingDirection = Enum.ScrollingDirection.Y}, f)
	mk("UIListLayout", {Padding = UDim.new(0, 7), SortOrder = Enum.SortOrder.LayoutOrder}, sf)
	mk("UIPadding", {PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12), PaddingTop = UDim.new(0, 2), PaddingBottom = UDim.new(0, 8)}, sf)
	return sf
end

local function swatch(parent, tbl, key)
	local b = mk("TextButton", {Text = "", AutoButtonColor = false, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0),
		Size = UDim2.fromOffset(18, 18), BackgroundColor3 = tbl[key], BorderSizePixel = 0}, parent)
	corner(b, 4); stroke(b, Color3.fromRGB(95, 95, 115), 1, 0.4)
	conn(b.Activated:Connect(function()
		local idx = 0
		for i, p in ipairs(PALETTE) do if p == tbl[key] then idx = i end end
		idx = idx % #PALETTE + 1
		tbl[key] = PALETTE[idx]
		b.BackgroundColor3 = PALETTE[idx]
		changed()
	end))
end

-- Checkbox roxo com icone de check estilo foto
local function addCheck(list, str, tbl, key, indent, colorKey)
	local r = mk("TextButton", {Text = "", AutoButtonColor = false, Size = UDim2.new(1, 0, 0, 20), BackgroundTransparency = 1,
		BorderSizePixel = 0, LayoutOrder = nextOrder(list)}, list)
	local x = (indent or 0) * 16
	local box = mk("Frame", {Position = UDim2.fromOffset(x, 2), Size = UDim2.fromOffset(16, 16),
		BackgroundColor3 = tbl[key] and C.accBright or C.off, BorderSizePixel = 0}, r)
	corner(box, 4)
	local mark = mk("Frame", {Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Visible = tbl[key]}, box)
	mk("Frame", {AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(5.2, 9.2), Size = UDim2.fromOffset(2, 5.2),
		Rotation = -42, BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0}, mark)
	mk("Frame", {AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(9.8, 7.6), Size = UDim2.fromOffset(2, 9.2),
		Rotation = 42, BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0}, mark)
	local lbl = text(r, str, 11, F.GothamMedium, tbl[key] and C.text or C.mute, x + 24, 0, 155, 20)
	lbl.TextTruncate = Enum.TextTruncate.AtEnd
	if colorKey then swatch(r, tbl, colorKey) end
	local function sync()
		local v = tbl[key]
		mark.Visible = v
		box.BackgroundColor3 = v and C.accBright or C.off
		lbl.TextColor3 = v and C.text or C.mute
	end
	conn(r.Activated:Connect(function()
		local v = not tbl[key]
		tbl[key] = v
		mark.Visible = v
		lbl.TextColor3 = v and C.text or C.mute
		tw(box, 0.12, {BackgroundColor3 = v and C.accBright or C.off})
		changed()
	end))
	return r, sync
end

local function addColor(list, str, tbl, key)
	local r = mk("Frame", {Size = UDim2.new(1, 0, 0, 20), BackgroundTransparency = 1, LayoutOrder = nextOrder(list)}, list)
	text(r, str, 11, F.GothamMedium, C.text, 0, 0, 145, 20)
	swatch(r, tbl, key)
end

-- Slider estilo foto (label a esquerda, valor a direita, barra roxa com knob redondo)
local function addSlider(list, str, tbl, key, mn, mx, step, suffix, fmtStr)
	local r = mk("Frame", {Size = UDim2.new(1, 0, 0, 32), BackgroundTransparency = 1, LayoutOrder = nextOrder(list)}, list)
	text(r, str, 10.5, F.GothamMedium, C.text, 0, 0, 135, 14)
	local val = mk("TextLabel", {Text = "", TextSize = 10, Font = F.Gotham, TextColor3 = C.mute, BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, 0, 0, 0), Size = UDim2.fromOffset(75, 14), TextXAlignment = Enum.TextXAlignment.Right}, r)
	local track = mk("Frame", {Position = UDim2.fromOffset(0, 21), Size = UDim2.new(1, 0, 0, 3), BackgroundColor3 = C.off, BorderSizePixel = 0}, r)
	corner(track, 2)
	local fill = mk("Frame", {Size = UDim2.fromScale(0, 1), BackgroundColor3 = C.accBright, BorderSizePixel = 0}, track)
	corner(fill, 2)
	local knob = mk("Frame", {AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0, 0.5), Size = UDim2.fromOffset(11, 11),
		BackgroundColor3 = C.accBright, BorderSizePixel = 0}, track)
	corner(knob, 6)
	stroke(knob, Color3.fromRGB(210, 185, 255), 1, 0.4)
	local hit = mk("TextButton", {Text = "", AutoButtonColor = false, BackgroundTransparency = 1, Position = UDim2.fromOffset(-4, 10), Size = UDim2.new(1, 8, 0, 22)}, r)
	local function render()
		local v = tbl[key]
		local rel = math.clamp((v - mn) / math.max(mx - mn, 1e-6), 0, 1)
		fill.Size = UDim2.fromScale(rel, 1)
		knob.Position = UDim2.fromScale(rel, 0.5)
		if fmtStr then
			val.Text = string.format(fmtStr, v) .. (suffix or "")
		else
			val.Text = (step >= 1 and string.format("%d", v) or string.format("%.2f", v)) .. (suffix or "")
		end
	end
	render()
	local dragging
	local function setFrom(x)
		local rel = math.clamp((x - track.AbsolutePosition.X) / math.max(track.AbsoluteSize.X, 1), 0, 1)
		local v = mn + rel * (mx - mn)
		v = math.clamp(math.floor(v / step + 0.5) * step, mn, mx)
		tbl[key] = tonumber(string.format("%.3f", v))
		render()
		changed()
	end
	conn(hit.InputBegan:Connect(function(i)
		if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
			dragging = i
			list.ScrollingEnabled = false
			setFrom(i.Position.X)
			i.Changed:Connect(function()
				if i.UserInputState == Enum.UserInputState.End and dragging == i then
					dragging = nil
					list.ScrollingEnabled = true
				end
			end)
		end
	end))
	conn(UIS.InputChanged:Connect(function(i)
		if dragging and (i == dragging or i.UserInputType == Enum.UserInputType.MouseMovement) then setFrom(i.Position.X) end
	end))
end

local function addDrop(list, str, tbl, key, opts)
	local r = mk("Frame", {Size = UDim2.new(1, 0, 0, 40), BackgroundTransparency = 1, ClipsDescendants = true, LayoutOrder = nextOrder(list)}, list)
	text(r, str, 10.5, F.GothamMedium, C.mute, 0, 0, 180, 14)
	local hd = mk("TextButton", {Text = "", AutoButtonColor = false, Position = UDim2.fromOffset(0, 16), Size = UDim2.new(1, 0, 0, 22),
		BackgroundColor3 = C.field, BorderSizePixel = 0}, r)
	corner(hd, 5)
	local cur = text(hd, tbl[key], 11, F.GothamMedium, C.text, 8, 0, 140, 22)
	mk("TextLabel", {Text = "▼", TextSize = 8, Font = F.Gotham, TextColor3 = C.mute, BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -8, 0.5, 0), Size = UDim2.fromOffset(12, 12)}, hd)
	local open = false
	local function setOpen(v)
		open = v
		r.Size = UDim2.new(1, 0, 0, v and (42 + #opts * 21) or 40)
	end
	for i, o in ipairs(opts) do
		local b = mk("TextButton", {Text = o, Font = F.Gotham, TextSize = 11, TextColor3 = C.text, AutoButtonColor = false,
			Position = UDim2.fromOffset(0, 40 + (i - 1) * 21), Size = UDim2.new(1, 0, 0, 19), BackgroundColor3 = C.field,
			BackgroundTransparency = 0.2, BorderSizePixel = 0}, r)
		corner(b, 4)
		conn(b.Activated:Connect(function()
			tbl[key] = o
			cur.Text = o
			setOpen(false)
			changed()
		end))
	end
	conn(hd.Activated:Connect(function() setOpen(not open) end))
end

