	local btnRow = mk("Frame", {Position = UDim2.fromOffset(8, 74), Size = UDim2.new(1, -16, 0, 19), BackgroundTransparency = 1}, rightFrame)
	local bOn = mk("TextButton", {Text = "Enable Filtered", Font = F.GothamBold, TextSize = 9, TextColor3 = Color3.new(1,1,1),
		Size = UDim2.new(0.48, 0, 1, 0), BackgroundColor3 = C.accBright, BorderSizePixel = 0}, btnRow)
	corner(bOn, 4)
	local bOff = mk("TextButton", {Text = "Disable All", Font = F.GothamBold, TextSize = 9, TextColor3 = C.text,
		Position = UDim2.new(0.52, 0, 0, 0), Size = UDim2.new(0.48, 0, 1, 0), BackgroundColor3 = C.field, BorderSizePixel = 0}, btnRow)
	corner(bOff, 4)

	local espScroll = mk("ScrollingFrame", {
		Position = UDim2.fromOffset(0, 97), Size = UDim2.new(1, 0, 1, -100), BackgroundTransparency = 1, BorderSizePixel = 0,
		ScrollBarThickness = 2, ScrollBarImageColor3 = C.accBright, CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollingDirection = Enum.ScrollingDirection.Y
	}, rightFrame)
	mk("UIListLayout", {Padding = UDim.new(0, 5), SortOrder = Enum.SortOrder.LayoutOrder}, espScroll)
	mk("UIPadding", {PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10), PaddingTop = UDim.new(0, 2), PaddingBottom = UDim.new(0, 8)}, espScroll)

	local espRows = {}
	for _, cat in ipairs(ESP_CATEGORIES) do
		for _, optName in ipairs(cat.items) do
			local row, syncFn = addCheck(espScroll, optName, E.flags, optName)
			espRows[#espRows + 1] = {name = optName, cat = cat.name, lower = string.lower(optName), row = row, sync = syncFn}
		end
	end

	local function applyFilter()
		local q = string.lower(searchBox.Text or "")
		local c = catState.cat
		for _, item in ipairs(espRows) do
			local matchCat = (c == "Todas" or item.cat == c)
			local matchTxt = (q == "" or string.find(item.lower, q, 1, true) ~= nil)
			item.row.Visible = matchCat and matchTxt
