	local f = E.flags
	local anyCross = A.cross or (E.master and (f["ESP Crosshair"] or f["ESP Crosshair Cross"] or f["ESP Crosshair Dot"]
		or f["ESP Crosshair Circle"] or f["ESP Crosshair T"] or f["ESP Center Dot"] or f["ESP Center Ring"]
		or f["ESP Center Cross"] or f["ESP HUD Dot"] or f["ESP HUD Ring"] or f["ESP Retina Dot"] or f["ESP Focus Ring"]))
	local s, g, t = A.crossSize, f["ESP Crosshair Gap"] and (A.crossGap + 4) or A.crossGap, 2
	crossHolder.Visible = anyCross
	local showArms = A.cross or (E.master and (f["ESP Crosshair"] or f["ESP Crosshair Cross"] or f["ESP Crosshair T"] or f["ESP Center Cross"]))
	for i = 1, 4 do arms[i].Visible = showArms end
	if E.master and f["ESP Crosshair T"] then arms[1].Visible = false end
	arms[1].Position, arms[1].Size = UDim2.fromOffset(-t / 2, -(g + s)), UDim2.fromOffset(t, s)
	arms[2].Position, arms[2].Size = UDim2.fromOffset(-t / 2, g), UDim2.fromOffset(t, s)
	arms[3].Position, arms[3].Size = UDim2.fromOffset(-(g + s), -t / 2), UDim2.fromOffset(s, t)
	arms[4].Position, arms[4].Size = UDim2.fromOffset(g, -t / 2), UDim2.fromOffset(s, t)
	for _, a in ipairs(arms) do a.BackgroundColor3 = A.crossColor end
	crossDot.Visible = E.master and (f["ESP Crosshair Dot"] or f["ESP Center Dot"] or f["ESP HUD Dot"] or f["ESP Retina Dot"])
	crossDot.BackgroundColor3 = A.crossColor
	crossRing.Visible = E.master and (f["ESP Crosshair Circle"] or f["ESP Center Ring"] or f["ESP HUD Ring"] or f["ESP Focus Ring"])
	crossRingStroke.Color = A.crossColor
end
updateCross()

