local Cam = Workspace.CurrentCamera
conn(Workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function() Cam = Workspace.CurrentCamera end))

local function sameTeam(p) return p.Team ~= nil and LP and LP.Team ~= nil and p.Team == LP.Team end
local function w2s(p)
	if not Cam then return Vector2.zero, 0 end
	local v = Cam:WorldToViewportPoint(p)
	return Vector2.new(v.X, v.Y), v.Z
end

local rayParams = RaycastParams.new()
rayParams.FilterType = Enum.RaycastFilterType.Exclude
pcall(function() rayParams.RespectCanCollide = true end)
local function isVisible(char, part)
	if not Cam then return true end
	local ign = {char, Cam}
	if LP and LP.Character then ign[#ign + 1] = LP.Character end
	rayParams.FilterDescendantsInstances = ign
	local o = Cam.CFrame.Position
	local ok, res = pcall(function() return Workspace:Raycast(o, part.Position - o, rayParams) end)
	return not ok or res == nil
end

local function getRigParts(char)
	local head = char:FindFirstChild("Head")
	local hrp = char:FindFirstChild("HumanoidRootPart")
	local isR15 = char:FindFirstChild("UpperTorso") ~= nil
	if isR15 then
		return {
			isR15 = true, head = head, hrp = hrp,
			uTorso = char:FindFirstChild("UpperTorso"),
			lTorso = char:FindFirstChild("LowerTorso"),
			lUArm = char:FindFirstChild("LeftUpperArm"), lLArm = char:FindFirstChild("LeftLowerArm"), lHand = char:FindFirstChild("LeftHand"),
			rUArm = char:FindFirstChild("RightUpperArm"), rLArm = char:FindFirstChild("RightLowerArm"), rHand = char:FindFirstChild("RightHand"),
			lULeg = char:FindFirstChild("LeftUpperLeg"), lLLeg = char:FindFirstChild("LeftLowerLeg"), lFoot = char:FindFirstChild("LeftFoot"),
			rULeg = char:FindFirstChild("RightUpperLeg"), rLLeg = char:FindFirstChild("RightLowerLeg"), rFoot = char:FindFirstChild("RightFoot"),
		}
	else
		local torso = char:FindFirstChild("Torso")
		local lArm = char:FindFirstChild("Left Arm")
		local rArm = char:FindFirstChild("Right Arm")
		local lLeg = char:FindFirstChild("Left Leg")
		local rLeg = char:FindFirstChild("Right Leg")
		return {
			isR15 = false, head = head, hrp = hrp,
			uTorso = torso, lTorso = torso,
			lUArm = lArm, lLArm = lArm, lHand = lArm,
			rUArm = rArm, rLArm = rArm, rHand = rArm,
			lULeg = lLeg, lLLeg = lLeg, lFoot = lLeg,
			rULeg = rLeg, rLLeg = rLeg, rFoot = rLeg,
		}
	end
end

local NEAR_PARTS = {"Head", "UpperTorso", "Torso", "LowerTorso", "HumanoidRootPart", "LeftUpperArm", "RightUpperArm",
	"Left Arm", "Right Arm", "LeftUpperLeg", "RightUpperLeg", "Left Leg", "Right Leg"}

local function aimPart(char, center)
	if A.part == "Cabeça" then
		return char:FindFirstChild("Head") or char:FindFirstChild("HumanoidRootPart")
	elseif A.part == "Tronco" then
		return char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso") or char:FindFirstChild("HumanoidRootPart")
	elseif A.part == "Pelve" then
		return char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("LowerTorso") or char:FindFirstChild("Torso")
	end
	local best, bd = nil, math.huge
	for _, n in ipairs(NEAR_PARTS) do
		local pt = char:FindFirstChild(n)
		if pt and pt:IsA("BasePart") then
			local sp, z = w2s(pt.Position)
			if z > 0 then
				local dd = (sp - center).Magnitude
				if dd < bd then best, bd = pt, dd end
			end
		end
	end
	return best or char:FindFirstChild("HumanoidRootPart")
end

local function evaluate(p, center, needFov)
	if not Cam then return nil end
	local char = p.Character
	if not char then return nil end
	local hum = char:FindFirstChildOfClass("Humanoid")
	if not hum or hum.Health <= 0 then return nil end
	if A.teamCheck and sameTeam(p) then return nil end
	if A.ignoreFF and char:FindFirstChildOfClass("ForceField") then return nil end
	local part = aimPart(char, center)
	if not part then return nil end
	local aimPos = part.Position
	if A.predict then
		local rt = char:FindFirstChild("HumanoidRootPart") or part
		aimPos = aimPos + rt.AssemblyLinearVelocity * (A.predictAmt / 100)
	end
	local d = (aimPos - Cam.CFrame.Position).Magnitude
	if d > A.maxDist then return nil end
	local sp, z = w2s(aimPos)
	if z <= 0 then return nil end
	local sd = (sp - center).Magnitude
	if needFov and sd > A.fov then return nil end
	if A.wallCheck and not isVisible(char, part) then return nil end
	return {p = p, part = part, pos = aimPos, sp = sp, sd = sd, d = d, hum = hum}
end

local function smoothAlpha(pct, dt)
	local base = math.clamp(1 - pct / 100 * 0.97, 0.03, 1)
	return 1 - (1 - base) ^ math.clamp(dt * 60, 0.2, 3)
end

local function steer(pos, aH, aV)
	if not Cam then return end
	local cf = Cam.CFrame
	local look = cf.LookVector
	local dir = pos - cf.Position
	if dir.Magnitude < 1e-3 then return end
	dir = dir.Unit
	local cy, cp = math.atan2(-look.X, -look.Z), math.asin(math.clamp(look.Y, -1, 1))
	local ty, tp = math.atan2(-dir.X, -dir.Z), math.asin(math.clamp(dir.Y, -1, 1))
	local dy = (ty - cy + math.pi) % (2 * math.pi) - math.pi
	Cam.CFrame = CFrame.new(cf.Position) * CFrame.fromOrientation(cp + (tp - cp) * aV, cy + dy * aH, 0)
end


------------------------------------------------------------ MODULO #001: ESP Box
local function ESP_Handler_001(ctx)
	local f = ctx.flags
	if not f["ESP Box"] then return false end
	local col = ctx.col
	local alpha = ctx.alpha
	local th = ctx.th
	local x, y, w, h = ctx.x, ctx.y, ctx.w, ctx.h
	local cx, cy = ctx.cx, ctx.cy
	local obj = ctx.obj
	local rig = ctx.rig
	local hum = ctx.hum
	local dist = ctx.dist
	local pulse = ctx.pulse

	if string.find("ESP Box", "Box", 1, true) then
		obj.box.Visible = true
		obj.box.Position = UDim2.fromOffset(x, y)
		obj.box.Size = UDim2.fromOffset(w, h)
		obj.boxStroke.Color = col
		obj.boxStroke.Thickness = th
		obj.boxStroke.Transparency = 1 - alpha
		if string.find("ESP Box", "Filled", 1, true) then
			obj.box.BackgroundColor3 = col
			obj.box.BackgroundTransparency = 1 - alpha * 0.25
		else
			obj.box.BackgroundTransparency = 1
		end
		if string.find("ESP Box", "Corner", 1, true) or string.find("ESP Box", "Bracket", 1, true) then
			local cl = math.min(w, h) * 0.28
			local pts = {{x, y, cl, th}, {x, y, th, cl}, {x+w-cl, y, cl, th}, {x+w-th, y, th, cl}, {x, y+h-th, cl, th}, {x, y+h-cl, th, cl}, {x+w-cl, y+h-th, cl, th}, {x+w-th, y+h-cl, th, cl}}
			for i = 1, 8 do
				obj.corners[i].Position = UDim2.fromOffset(pts[i][1], pts[i][2])
				obj.corners[i].Size = UDim2.fromOffset(pts[i][3], pts[i][4])
				obj.corners[i].BackgroundColor3 = col
				obj.corners[i].BackgroundTransparency = 1 - alpha
				obj.corners[i].Visible = true
			end
		end
		if string.find("ESP Box", "Pulsing", 1, true) or string.find("ESP Box", "Breathing", 1, true) then
			obj.boxStroke.Transparency = 1 - (alpha * (0.4 + 0.6 * pulse))
		end
	elseif string.find("ESP Box", "Skeleton", 1, true) or string.find("ESP Box", "Bone", 1, true) then
		ctx.wantSkel = true
	elseif string.find("ESP Box", "Joint", 1, true) or string.find("ESP Box", "Head ", 1, true) then
		ctx.wantHeadOrJoint = true
	elseif string.find("ESP Box", "Tracer", 1, true) or string.find("ESP Box", "Snapline", 1, true) then
		ctx.wantTracer = true
	elseif string.find("ESP Box", "Health", 1, true) or string.find("ESP Box", "Armor", 1, true) or string.find("ESP Box", "Shield", 1, true) then
		ctx.wantBars = true
	elseif string.find("ESP Box", "Name", 1, true) or string.find("ESP Box", "User", 1, true) or string.find("ESP Box", "Distance", 1, true) then
		ctx.wantLabels = true
	elseif string.find("ESP Box", "Chams", 1, true) or string.find("ESP Box", "Highlight", 1, true) or string.find("ESP Box", "Glow", 1, true) then
		ctx.wantChams = true
	end
	return true
end
ESP_REGISTRY["ESP Box"] = ESP_Handler_001


