	local f = ctx.flags
	if not f["ESP Top Edge Box"] then return false end
	local col = ctx.col
	local alpha = ctx.alpha
	local th = ctx.th
	local x, y, w, h = ctx.x, ctx.y, ctx.w, ctx.h
	local cx, cy = ctx.cx, ctx.cy
	local obj = ctx.obj
	local rig = ctx.rig
	local hum = ctx.hum
	local dist = ctx.dist
	local pulse = ctx.pulse

	if string.find("ESP Top Edge Box", "Box", 1, true) then
		obj.box.Visible = true
		obj.box.Position = UDim2.fromOffset(x, y)
		obj.box.Size = UDim2.fromOffset(w, h)
		obj.boxStroke.Color = col
		obj.boxStroke.Thickness = th
		obj.boxStroke.Transparency = 1 - alpha
		if string.find("ESP Top Edge Box", "Filled", 1, true) then
			obj.box.BackgroundColor3 = col
			obj.box.BackgroundTransparency = 1 - alpha * 0.25
		else
			obj.box.BackgroundTransparency = 1
		end
		if string.find("ESP Top Edge Box", "Corner", 1, true) or string.find("ESP Top Edge Box", "Bracket", 1, true) then
			local cl = math.min(w, h) * 0.28
			local pts = {{x, y, cl, th}, {x, y, th, cl}, {x+w-cl, y, cl, th}, {x+w-th, y, th, cl}, {x, y+h-th, cl, th}, {x, y+h-cl, th, cl}, {x+w-cl, y+h-th, cl, th}, {x+w-th, y+h-cl, th, cl}}
			for i = 1, 8 do
				obj.corners[i].Position = UDim2.fromOffset(pts[i][1], pts[i][2])
				obj.corners[i].Size = UDim2.fromOffset(pts[i][3], pts[i][4])
				obj.corners[i].BackgroundColor3 = col
				obj.corners[i].BackgroundTransparency = 1 - alpha
				obj.corners[i].Visible = true
			end
		end
		if string.find("ESP Top Edge Box", "Pulsing", 1, true) or string.find("ESP Top Edge Box", "Breathing", 1, true) then
			obj.boxStroke.Transparency = 1 - (alpha * (0.4 + 0.6 * pulse))
		end
	elseif string.find("ESP Top Edge Box", "Skeleton", 1, true) or string.find("ESP Top Edge Box", "Bone", 1, true) then
		ctx.wantSkel = true
	elseif string.find("ESP Top Edge Box", "Joint", 1, true) or string.find("ESP Top Edge Box", "Head ", 1, true) then
		ctx.wantHeadOrJoint = true
	elseif string.find("ESP Top Edge Box", "Tracer", 1, true) or string.find("ESP Top Edge Box", "Snapline", 1, true) then
		ctx.wantTracer = true
	elseif string.find("ESP Top Edge Box", "Health", 1, true) or string.find("ESP Top Edge Box", "Armor", 1, true) or string.find("ESP Top Edge Box", "Shield", 1, true) then
		ctx.wantBars = true
	elseif string.find("ESP Top Edge Box", "Name", 1, true) or string.find("ESP Top Edge Box", "User", 1, true) or string.find("ESP Top Edge Box", "Distance", 1, true) then
		ctx.wantLabels = true
	elseif string.find("ESP Top Edge Box", "Chams", 1, true) or string.find("ESP Top Edge Box", "Highlight", 1, true) or string.find("ESP Top Edge Box", "Glow", 1, true) then
		ctx.wantChams = true
	end
	return true
end
ESP_REGISTRY["ESP Top Edge Box"] = ESP_Handler_041


