local espPool = {}

local function anyFlagPrefix(prefix)
	for k, v in pairs(E.flags) do
		if v and string.sub(k, 1, #prefix) == prefix then return true end
	end
	return false
end

local function getEspObj(p)
	if espPool[p] then return espPool[p] end
	local holder = mk("Frame", {BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Visible = false}, espFolder)
	local box = mk("Frame", {BackgroundTransparency = 1, BorderSizePixel = 0, Visible = false}, holder)
	local boxStroke = stroke(box, E.color, 1.5)
	local boxCorner = corner(box, 0)

	local corners = {}
	for i = 1, 8 do
		corners[i] = mk("Frame", {BorderSizePixel = 0, BackgroundColor3 = E.color, Visible = false}, holder)
	end

	local skelLines = {}
	for i = 1, 14 do
		skelLines[i] = mk("Frame", {AnchorPoint = Vector2.new(0.5, 0.5), BorderSizePixel = 0, BackgroundColor3 = E.color, Visible = false}, holder)
	end

	local jointDots = {}
	for i = 1, 10 do
		jointDots[i] = mk("Frame", {AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(4, 4), BorderSizePixel = 0, BackgroundColor3 = E.secColor, Visible = false}, holder)
		corner(jointDots[i], 4)
	end

	local hpBg = mk("Frame", {BackgroundColor3 = Color3.fromRGB(12, 12, 16), BorderSizePixel = 0, Visible = false}, holder)
	local hpFill = mk("Frame", {BackgroundColor3 = Color3.fromRGB(70, 255, 130), BorderSizePixel = 0}, hpBg)

	local nameLbl = mk("TextLabel", {BackgroundTransparency = 1, Font = F.GothamBold, TextSize = 11, TextColor3 = C.text,
		TextStrokeTransparency = 0.35, Visible = false}, holder)
	local infoLbl = mk("TextLabel", {BackgroundTransparency = 1, Font = F.Gotham, TextSize = 9, TextColor3 = C.mute,
		TextStrokeTransparency = 0.35, Visible = false}, holder)

	local tracer = mk("Frame", {AnchorPoint = Vector2.new(0.5, 0.5), BorderSizePixel = 0, BackgroundColor3 = E.color, Visible = false}, holder)
	local offArrow = mk("TextLabel", {AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(18, 18), BackgroundTransparency = 1,
		Text = "▲", Font = F.GothamBold, TextSize = 13, TextColor3 = E.color, Visible = false}, holder)

	local hl = mk("Highlight", {Name = "yoshzzk_HL", Enabled = false}, worldFolder)

	local obj = {
		holder = holder, box = box, boxStroke = boxStroke, boxCorner = boxCorner,
		corners = corners, skelLines = skelLines, jointDots = jointDots,
		hpBg = hpBg, hpFill = hpFill, nameLbl = nameLbl, infoLbl = infoLbl,
		tracer = tracer, offArrow = offArrow, hl = hl
	}
	espPool[p] = obj
	return obj
end

local function removeEspObj(p)
	local obj = espPool[p]
	if obj then
		pcall(function() if obj.holder then obj.holder:Destroy() end end)
		pcall(function() if obj.hl then obj.hl:Destroy() end end)
		espPool[p] = nil
	end
	if radarBlips[p] then
		pcall(function() radarBlips[p]:Destroy() end)
		radarBlips[p] = nil
	end
end
conn(Players.PlayerRemoving:Connect(removeEspObj))

local function drawLine2D(frame, a, b, th, col, alpha)
	if not frame then return end
	local dx, dy = b.X - a.X, b.Y - a.Y
	local len = math.sqrt(dx * dx + dy * dy)
	if len < 1 then frame.Visible = false return end
	frame.Position = UDim2.fromOffset((a.X + b.X) / 2, (a.Y + b.Y) / 2)
	frame.Size = UDim2.fromOffset(len, th)
	frame.Rotation = math.deg(math.atan2(dy, dx))
	frame.BackgroundColor3 = col
	frame.BackgroundTransparency = 1 - alpha
	frame.Visible = true
end

local function espStep(dt)
	if not Cam then return end
	local f = E.flags
	local vp = Cam.ViewportSize
	local now = os.clock()
	local pulse = 0.5 + 0.5 * math.sin(now * 5)

	screenBorder.Visible = E.master and (f["ESP Screen Border"] or f["ESP Screen Edge"] or f["ESP Screen Frame"])
	if screenBorder.Visible then screenBorderStroke.Color = E.color end
	axisX.Visible = E.master and (f["ESP Screen Grid"] or f["ESP Grid Overlay"] or f["ESP Axis Line"] or f["ESP Axis X"])
	axisY.Visible = E.master and (f["ESP Screen Grid"] or f["ESP Grid Overlay"] or f["ESP Axis Line"] or f["ESP Axis Y"])

	compassBar.Visible = E.master and (f["ESP Compass"] or f["ESP Compass Bar"] or f["ESP Heading Bar"])
	if compassBar.Visible then
		local look = Cam.CFrame.LookVector
		local deg = math.floor((math.deg(math.atan2(-look.X, -look.Z)) + 360) % 360)
		compassTxt.Text = string.format("HDG  ·  %d°", deg)
	end

	local showRadar = E.master and (anyFlagPrefix("ESP Radar") or anyFlagPrefix("ESP Minimap"))
	radarFrame.Visible = showRadar
	if showRadar then
		local sz = E.radarSize
		radarFrame.Size = UDim2.fromOffset(sz, sz)
		radarCorner.CornerRadius = UDim.new(0, f["ESP Radar Circle"] and (sz / 2) or 10)
		radarStroke.Color = E.color
		radarRingOuter.Visible = true
		radarRingInner.Visible = true
		radarSweep.Visible = true
		radarSweep.Rotation = (now * 140) % 360
		radarNorth.Size = UDim2.fromOffset(sz, 12)
	end

	if not E.master then
		for _, obj in pairs(espPool) do
			obj.holder.Visible = false
			if obj.hl then obj.hl.Enabled = false end
		end
		return
	end

	local myPos = (LP and LP.Character and LP.Character:FindFirstChild("HumanoidRootPart") and LP.Character.HumanoidRootPart.Position) or Cam.CFrame.Position

	for _, p in ipairs(Players:GetPlayers()) do
		if LP and p == LP and not f["ESP Include Self"] then
			removeEspObj(p)
			continue
		end
		local obj = getEspObj(p)
		local char = p.Character
		local hum = char and char:FindFirstChildOfClass("Humanoid")
		local rig = char and getRigParts(char)
		local hrp = rig and rig.hrp
		local head = rig and rig.head

		if not char or not hrp or not hum or hum.Health <= 0 then
			obj.holder.Visible = false
			if obj.hl then obj.hl.Enabled = false end
			if radarBlips[p] then radarBlips[p].Visible = false end
			continue
		end

		if (f["ESP Team Check"] or f["ESP Ignore Team"]) and sameTeam(p) then
			obj.holder.Visible = false
			if obj.hl then obj.hl.Enabled = false end
			if radarBlips[p] then radarBlips[p].Visible = false end
			continue
		end

		local dist = (hrp.Position - myPos).Magnitude
		if dist > E.maxDist then
			obj.holder.Visible = false
			if obj.hl then obj.hl.Enabled = false end
			if radarBlips[p] then radarBlips[p].Visible = false end
			continue
		end

		local vis = isVisible(char, head or hrp)
		if f["ESP Visible Only"] and not vis then obj.holder.Visible = false if obj.hl then obj.hl.Enabled = false end continue end
		if f["ESP Hidden Only"] and vis then obj.holder.Visible = false if obj.hl then obj.hl.Enabled = false end continue end

		local col = f["ESP Visibility Check"] and (vis and E.visColor or E.hidColor) or E.color
		local alpha = math.clamp(E.opacity / 100, 0.1, 1)
		local top2D = w2s((head and head.Position + Vector3.new(0, 0.85, 0)) or (hrp.Position + Vector3.new(0, 2.8, 0)))
		local bot2D = w2s(hrp.Position - Vector3.new(0, 2.8, 0))
		local center2D, zc = w2s(hrp.Position)

		local h = math.max(math.abs(bot2D.Y - top2D.Y), 14)
		local w = h * 0.6
		local x = center2D.X - w / 2
		local y = top2D.Y

		obj.box.Visible = false
		for i = 1, 8 do obj.corners[i].Visible = false end
		obj.holder.Visible = zc > 0

		local ctx = {
			flags = f, col = col, alpha = alpha, th = E.thickness,
			x = x, y = y, w = w, h = h, cx = center2D.X, cy = center2D.Y,
			obj = obj, rig = rig, hum = hum, dist = dist, pulse = pulse,
			wantSkel = false, wantHeadOrJoint = false, wantTracer = false,
			wantBars = false, wantLabels = false, wantChams = false
		}

		for _, optName in ipairs(ESP_LIST) do
			if f[optName] and ESP_REGISTRY[optName] then
				ESP_REGISTRY[optName](ctx)
			end
		end

		if ctx.wantSkel then
			local bonePairs = {
				{rig.head, rig.uTorso}, {rig.uTorso, rig.lTorso},
				{rig.uTorso, rig.lUArm}, {rig.lUArm, rig.lLArm}, {rig.lLArm, rig.lHand},
				{rig.uTorso, rig.rUArm}, {rig.rUArm, rig.rLArm}, {rig.rLArm, rig.rHand},
				{rig.lTorso, rig.lULeg}, {rig.lULeg, rig.lLLeg}, {rig.lLLeg, rig.lFoot},
				{rig.lTorso, rig.rULeg}, {rig.rULeg, rig.rLLeg}, {rig.rLLeg, rig.rFoot},
			}
			for i = 1, 14 do
				local p1, p2 = bonePairs[i][1], bonePairs[i][2]
				if p1 and p2 and p1 ~= p2 then
					local s1, z1 = w2s(p1.Position)
					local s2, z2 = w2s(p2.Position)
					if z1 > 0 and z2 > 0 then drawLine2D(obj.skelLines[i], s1, s2, 1.4, E.secColor, alpha) else obj.skelLines[i].Visible = false end
				else
					obj.skelLines[i].Visible = false
				end
			end
		else
			for i = 1, 14 do obj.skelLines[i].Visible = false end
		end

		if ctx.wantHeadOrJoint and head then
			local hs, hz = w2s(head.Position)
			if hz > 0 then
				obj.jointDots[1].Position = UDim2.fromOffset(hs.X, hs.Y)
				obj.jointDots[1].Size = UDim2.fromOffset(8, 8)
				obj.jointDots[1].Visible = true
			else
				obj.jointDots[1].Visible = false
			end
		else
			for i = 1, 10 do obj.jointDots[i].Visible = false end
		end

		if ctx.wantBars and hum and zc > 0 then
			local hpPct = math.clamp(hum.Health / math.max(hum.MaxHealth, 1), 0, 1)
			obj.hpBg.Position = UDim2.fromOffset(x - 5, y)
			obj.hpBg.Size = UDim2.fromOffset(3, h)
			obj.hpFill.Position = UDim2.fromScale(0, 1 - hpPct)
			obj.hpFill.Size = UDim2.fromScale(1, hpPct)
			obj.hpFill.BackgroundColor3 = Color3.fromRGB(math.floor(255 * (1 - hpPct)), math.floor(255 * hpPct), 70)
			obj.hpBg.Visible = true
		else
			obj.hpBg.Visible = false
		end

		if ctx.wantLabels and zc > 0 then
			obj.nameLbl.Text = f["ESP Username"] and p.Name or p.DisplayName
			obj.nameLbl.TextColor3 = col
			obj.nameLbl.Size = UDim2.fromOffset(math.max(w + 60, 110), 14)
			obj.nameLbl.Position = UDim2.fromOffset(center2D.X - math.max(w + 60, 110) / 2, y - 15)
			obj.nameLbl.Visible = true

			obj.infoLbl.Text = string.format("%d st · %d HP", math.floor(dist), math.floor(hum.Health))
			obj.infoLbl.Size = UDim2.fromOffset(math.max(w + 70, 120), 12)
			obj.infoLbl.Position = UDim2.fromOffset(center2D.X - math.max(w + 70, 120) / 2, y + h + 3)
			obj.infoLbl.Visible = true
		else
			obj.nameLbl.Visible = false
			obj.infoLbl.Visible = false
		end

		if ctx.wantTracer and zc > 0 then
			drawLine2D(obj.tracer, Vector2.new(vp.X / 2, vp.Y), Vector2.new(center2D.X, y + h), E.thickness, col, alpha)
		else
			obj.tracer.Visible = false
		end

		if ctx.wantChams and obj.hl then
			obj.hl.Adornee = char
			obj.hl.Enabled = true
			obj.hl.FillColor = col
			obj.hl.OutlineColor = E.secColor
			obj.hl.FillTransparency = 1 - alpha * 0.35
			obj.hl.OutlineTransparency = 1 - alpha
		elseif obj.hl then
			obj.hl.Enabled = false
		end

		if showRadar then
			local blip = radarBlips[p]
			if not blip then
				blip = mk("Frame", {AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(6, 6), BorderSizePixel = 0}, radarFrame)
				corner(blip, 3)
				radarBlips[p] = blip
			end
			if blip then
				local rel = hrp.Position - myPos
				local look = Cam.CFrame.LookVector
				local yaw = math.atan2(-look.X, -look.Z)
				local rx = (rel.X * math.cos(yaw) - rel.Z * math.sin(yaw)) * (E.radarZoom * 0.35)
				local rz = (rel.X * math.sin(yaw) + rel.Z * math.cos(yaw)) * (E.radarZoom * 0.35)
				local half = radarFrame.AbsoluteSize.X / 2 - 6
				blip.Position = UDim2.new(0.5, math.clamp(rx, -half, half), 0.5, math.clamp(rz, -half, half))
				blip.BackgroundColor3 = col
				blip.Visible = true
			end
		end
	end
end

local AimState = {target = nil, locked = nil, since = 0, toggled = false, rmb = false, btn = false}
local noMouseWarned = false
local infoTimer = 0
local lastRev = -1

local function aimStep(dt)
	if not Cam then return end
	if cfgRev ~= lastRev then lastRev = cfgRev updateCross() end
	local center = (A.fovCenter == "Mouse" and UIS) and UIS:GetMouseLocation() or Cam.ViewportSize / 2

	fovFrame.Visible = (A.enabled and A.showFov) or (E.master and anyFlagPrefix("ESP FOV"))
	if fovFrame.Visible then
		fovFrame.Position = UDim2.fromOffset(center.X, center.Y)
		fovFrame.Size = UDim2.fromOffset(A.fov * 2, A.fov * 2)
		fovFrame.BackgroundColor3 = A.fovColor
		fovFrame.BackgroundTransparency = (A.fovFill or E.flags["ESP FOV Circle Filled"]) and 0.85 or 1
		fovStroke.Color = A.fovColor
	end
	aimLine.Visible = false

	infoTimer = infoTimer + dt
	local function setInfo(cand)
		if infoTimer < 0.1 then return end
		infoTimer = 0
		if statTarget then
			if cand then
				statTarget.Text = cand.p.DisplayName
				statDist.Text = string.format("%d st", math.floor(cand.d))
				statHp.Text = string.format("%d / %d", math.floor(cand.hum.Health), math.floor(cand.hum.MaxHealth))
			else
				statTarget.Text, statDist.Text, statHp.Text = "--", "--", "--"
			end
		end
	end

	if not A.enabled then
		AimState.target, AimState.locked = nil, nil
		setInfo(nil)
		return
	end
	local active = A.mode == "Sempre" or (A.mode == "Segurar" and (AimState.rmb or AimState.btn)) or (A.mode == "Alternar" and AimState.toggled)
	if not active then
		AimState.target, AimState.locked = nil, nil
		setInfo(nil)
		return
	end

	local cand
	if A.sticky and AimState.locked then
		cand = evaluate(AimState.locked, center, false)
		if not cand then AimState.locked = nil end
	end
	if not cand then
		local cur = AimState.target and evaluate(AimState.target, center, true)
		if cur and (os.clock() - AimState.since) * 1000 < A.switchCD then
			cand = cur
		else
			local bestScore = math.huge
			for _, p in ipairs(Players:GetPlayers()) do
				if not LP or p ~= LP then
					local ev = evaluate(p, center, true)
					if ev then
						local score = A.priority == "Perto de mim" and ev.d or (A.priority == "Menor vida" and (ev.hum.Health + ev.sd / 1000) or ev.sd)
						if score < bestScore then bestScore, cand = score, ev end
					end
				end
			end
			if cand and cand.p ~= AimState.target then AimState.since = os.clock() end
		end
	end
	if A.sticky and cand then AimState.locked = cand.p end
	AimState.target = cand and cand.p or nil
	setInfo(cand)
	if not cand then return end

	local aimPos = cand.pos
	if A.shake then
		local t = os.clock() * 4
		local s = A.shakeAmt / 40
		aimPos = aimPos + Vector3.new(math.noise(t, 0, 1), math.noise(0, t, 2), math.noise(t, t, 3)) * s
	end
	local aH, aV = smoothAlpha(A.smoothH, dt), smoothAlpha(A.smoothV, dt)
	if A.method == "Mouse" and mousemoverel then
		local delta = w2s(aimPos) - center
		if delta.Magnitude >= A.deadzone then mousemoverel(delta.X * aH, delta.Y * aV) end
	else
		if A.method == "Mouse" and not mousemoverel and not noMouseWarned then
			noMouseWarned = true
			toast("Usando câmera (sem mousemoverel)")
		end
		if cand.sd >= A.deadzone then steer(aimPos, aH, aV) end
	end

	if A.targetLine then
		local a, b = center, cand.sp
		local dx, dy = b.X - a.X, b.Y - a.Y
		aimLine.Position = UDim2.fromOffset((a.X + b.X) / 2, (a.Y + b.Y) / 2)
		aimLine.Size = UDim2.fromOffset(math.sqrt(dx * dx + dy * dy), 1.5)
		aimLine.Rotation = math.deg(math.atan2(dy, dx))
		aimLine.Visible = true
	end
end

if UIS then
	conn(UIS.InputBegan:Connect(function(i)
		if i.UserInputType == Enum.UserInputType.MouseButton2 then
			AimState.rmb = true
			if A.mode == "Alternar" then AimState.toggled = not AimState.toggled end
		end
	end))
	conn(UIS.InputEnded:Connect(function(i)
		if i.UserInputType == Enum.UserInputType.MouseButton2 then AimState.rmb = false end
	end))
end

local aimBtn = mk("TextButton", {Name = "AimBtn", Text = "AIM", Font = F.GothamBold, TextSize = 12, TextColor3 = C.neon, AutoButtonColor = false,
	AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(1, -68, 0.55, 0), Size = UDim2.fromOffset(50, 50),
	BackgroundColor3 = C.panel, BackgroundTransparency = 0.1, BorderSizePixel = 0, ZIndex = 20, Visible = false}, gui)
corner(aimBtn, 25)
local aimBtnStroke = stroke(aimBtn, C.accBright, 1.5)
do
	local drag, startIn, startPos, moved
	if aimBtn then
		conn(aimBtn.InputBegan:Connect(function(i)
			if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
				drag, startIn, startPos, moved = i, i.Position, aimBtn.Position, false
				if A.mode == "Segurar" then AimState.btn = true end
				i.Changed:Connect(function()
					if i.UserInputState == Enum.UserInputState.End and drag == i then
						drag = nil
						AimState.btn = false
						if not moved and A.mode == "Alternar" then AimState.toggled = not AimState.toggled end
					end
				end)
			end
		end))
	end
	if UIS then
		conn(UIS.InputChanged:Connect(function(i)
			if drag and aimBtn and (i == drag or i.UserInputType == Enum.UserInputType.MouseMovement) then
				local dlt = i.Position - startIn
				if dlt.Magnitude > 10 then moved = true AimState.btn = false end
				if moved then
					aimBtn.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + dlt.X, startPos.Y.Scale, startPos.Y.Offset + dlt.Y)
				end
			end
		end))
	end
end

conn(RunService.Heartbeat:Connect(function()
	if aimBtn then
		aimBtn.Visible = A.showBtn and A.mode ~= "Sempre"
		aimBtnStroke.Thickness = (AimState.btn or (A.mode == "Alternar" and AimState.toggled)) and 2.5 or 1.5
	end
end))

local function onTick(dt)
	local ok1, err1 = pcall(aimStep, dt)
	if not ok1 and not G.__yz_aimerr then
		G.__yz_aimerr = true
		warn("[yoshzzk] aimbot: " .. tostring(err1))
	end
	local ok2, err2 = pcall(espStep, dt)
	if not ok2 and not G.__yz_esperr then
		G.__yz_esperr = true
		warn("[yoshzzk] esp: " .. tostring(err2))
	end
end

local boundRenderStep = false
pcall(function()
	RunService:UnbindFromRenderStep("yoshzzk_loop")
	RunService:BindToRenderStep("yoshzzk_loop", Enum.RenderPriority.Camera.Value + 1, onTick)
	boundRenderStep = true
end)
if not boundRenderStep then
	conn(RunService.RenderStepped:Connect(onTick))
end

G.__yoshzzk = function()
	pcall(function() RunService:UnbindFromRenderStep("yoshzzk_loop") end)
	for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
	G.__yz_aimerr = nil
	G.__yz_esperr = nil
	pcall(function() if worldFolder then worldFolder:Destroy() end end)
	pcall(function() if gui then gui:Destroy() end end)
end

toast("TZ CyberHUD " .. VERSION .. " · Arceus Ready")

